}

// Plan returns one of an organization's plans.
func (s *Store) Plan(orgID, id string) (Plan, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.plans[id]
	if !ok || p.OrgID != orgID {
		return Plan{}, false
	}
	return p, true
}

// Plans returns an organization's plans, oldest first.
func (s *Store) Plans(orgID string) []Plan {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Plan{}
	for _, p := range s.plans {
		if p.OrgID == orgID {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
// depend on them.
func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.plans[id]
	if !ok || old.OrgID != orgID {
		return Plan{}, ErrNotFound
	}
	p := old
	if err := f(&p); err != nil {
		return Plan{}, err
	}
	p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
	p.Name = strings.TrimSpace(p.Name)
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.plans[id] = p
	return p, nil
}

// ---- subscriptions

// CreateSubscription stores a new subscription. The caller sets its status and periods.
func (s *Store) CreateSubscription(sub Subscription, now time.Time) (Subscription, error) {
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if sub.DiscountPercent < 0 || sub.DiscountPercent > 100 {
		return Subscription{}, invalid("the discount is 0 to 100 percent")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.customers[sub.CustomerID]; !ok {
		return Subscription{}, ErrNotFound
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
		return Subscription{}, ErrNotFound
	}
	sub.ID = s.newID("sub")
	sub.CreatedAt = now.UTC()
	s.subs[sub.ID] = sub
	return copySub(sub), nil
}

// Subscription returns one of an organization's subscriptions.
func (s *Store) Subscription(orgID, id string) (Subscription, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[id]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, false
	}
	return copySub(sub), true
}

// SubscriptionFilter narrows Subscriptions.
type SubscriptionFilter struct {
	CustomerID string
	Status     SubStatus
}

// Subscriptions returns an organization's subscriptions that match f, oldest first.
func (s *Store) Subscriptions(orgID string, f SubscriptionFilter) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.OrgID != orgID || (f.CustomerID != "" && sub.CustomerID != f.CustomerID) || (f.Status != "" && sub.Status != f.Status) {
			continue
		}
		out = append(out, copySub(sub))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdateSubscription changes a subscription with f, which may refuse with an error.
func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[id]
	if !ok || old.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	sub := copySub(old)
	if err := f(&sub); err != nil {
		return Subscription{}, err
	}
	sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	s.subs[id] = sub
	return copySub(sub), nil
}

// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
// canceled, the longest overdue first.
func (s *Store) DueSubscriptions(now time.Time) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
			out = append(out, copySub(sub))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
			return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

func copySub(sub Subscription) Subscription {
	if sub.TrialEnd != nil {
		t := *sub.TrialEnd
		sub.TrialEnd = &t
	}
	if sub.CanceledAt != nil {
		t := *sub.CanceledAt
		sub.CanceledAt = &t
	}
	return sub
}

// AddUsage records usage of a subscription to a metered plan at time at.
func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
	if quantity <= 0 {
		return UsageRecord{}, invalid("usage must be a positive quantity")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return UsageRecord{}, ErrNotFound
	}
	if p := s.plans[sub.PlanID]; p.UsageType != Metered {
		return UsageRecord{}, invalid("the subscription's plan is not metered")
	}
	u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
	s.usage = append(s.usage, u)
	return u, nil
}

// UsageTotal adds up a subscription's usage at times in [from, to).
func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	var n int64
	for _, u := range s.usage {
		if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
			n += u.Quantity
		}
	}
	return n
}

// ---- invoices

// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
	if !inv.Currency.Valid() {
		return Invoice{}, invalid("unknown currency %q", inv.Currency)
	}
	if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
		return Invoice{}, invalid("the discount is 0 to 100 percent")
	}
	for _, l := range inv.Lines {
		if l.Quantity <= 0 {
			return Invoice{}, invalid("a line needs a positive quantity")
		}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	org, ok := s.orgs[inv.OrgID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	c, ok := s.customers[inv.CustomerID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	if c.OrgID != inv.OrgID {
		return Invoice{}, ErrCustomerOrgMismatch
	}
	inv.ID = s.newID("in")
	inv.TaxRateBP = org.TaxRateBP
	inv.Status = InvoiceOpen
	inv.CreatedAt = now.UTC()
	inv.PaidAt, inv.VoidedAt = nil, nil
	inv = copyInvoice(inv)
	s.invoices[inv.ID] = inv
	return copyInvoice(inv), nil
}

// Invoice returns one of an organization's invoices.
func (s *Store) Invoice(orgID, id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	if !ok || inv.OrgID != orgID {
		return Invoice{}, false
	}
	return copyInvoice(inv), true
}

// InvoiceByID returns an invoice of any organization (background jobs and the admin tool).
func (s *Store) InvoiceByID(id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	return copyInvoice(inv), ok
}

// InvoiceFilter narrows ListInvoices.
type InvoiceFilter struct {
	CustomerID     string
	SubscriptionID string
	Status         InvoiceStatus
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	s.mu.Lock()
	all := make([]Invoice, 0, len(s.invoices))
	for _, inv := range s.invoices {
		all = append(all, inv)
	}
	s.mu.Unlock()
	out := []Invoice{}
	for _, inv := range all {
		c := cloneInvoice(inv)
		if c.OrgID != orgID {
			continue
		}
		if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
			continue
		}
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.invoices[id]
	if !ok || old.OrgID != orgID {
		return Invoice{}, ErrNotFound
	}
	inv := copyInvoice(old)
	if err := f(&inv); err != nil {
		return Invoice{}, err
	}
	inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
	s.invoices[id] = copyInvoice(inv)
	return copyInvoice(inv), nil
}

// copyInvoice is a deep copy, so callers cannot change stored lines.
func copyInvoice(inv Invoice) Invoice {
	inv.Lines = append([]Line(nil), inv.Lines...)
	for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
		if *p != nil {
			t := **p
			*p = &t
		}
	}
	return inv
}

// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
func cloneInvoice(inv Invoice) Invoice {
	b, err := json.Marshal(inv)
	if err != nil {
		return copyInvoice(inv)
	}
	var out Invoice
	if err := json.Unmarshal(b, &out); err != nil {
		return copyInvoice(inv)
	}
	return out
}

// ---- payments

// CreatePayment records a payment attempt for one of the organization's invoices.
func (s *Store) CreatePayment(p Payment, now time.Time) (Payment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[p.InvoiceID]
	if !ok || inv.OrgID != p.OrgID {
		return Payment{}, ErrNotFound
	}
	if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
		return Payment{}, invalid("a payment succeeded or failed")
	}
	p.ID = s.newID("pay")
	p.CreatedAt = now.UTC()
	s.payments[p.ID] = p
	return p, nil
}

// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
func (s *Store) Payments(orgID, invoiceID string) []Payment {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Payment{}
	for _, p := range s.payments {
		if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if err := s.renew(ctx, sub, now); err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		n++
	}
	return n, nil
}

func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return err
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
// payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// Runner runs jobs on its workers.
type Runner struct {
	queue   chan Job
	workers int
	log     *slog.Logger
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	return &Runner{queue: make(chan Job, queueSize), workers: workers, log: log}
}

// Start starts the workers.
func (r *Runner) Start() {
	for i := 0; i < r.workers; i++ {
		go r.work()
	}
}

func (r *Runner) work() {
	for j := range r.queue {
		if err := j.Run(context.Background()); err != nil {
			r.log.Error("job failed", "job", j.Name, "err", err)
		}
	}
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room.
func (r *Runner) Enqueue(j Job) error {
	select {
	case r.queue <- j:
		return nil
	default:
		return ErrQueueFull
	}
}

// Stop stops the runner.
func (r *Runner) Stop() {
	close(r.queue)
}

// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if err := s.renew(ctx, sub, now); err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		n++
	}
	return n, nil
}

func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return err
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
// payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// Runner runs jobs on its workers.
type Runner struct {
	queue   chan Job
	workers int
	log     *slog.Logger
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	return &Runner{queue: make(chan Job, queueSize), workers: workers, log: log}
}

// Start starts the workers.
func (r *Runner) Start() {
	for i := 0; i < r.workers; i++ {
		go r.work()
	}
}

func (r *Runner) work() {
	for j := range r.queue {
		if err := j.Run(context.Background()); err != nil {
			r.log.Error("job failed", "job", j.Name, "err", err)
		}
	}
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room.
func (r *Runner) Enqueue(j Job) error {
	select {
	case r.queue <- j:
		return nil
	default:
		return ErrQueueFull
	}
}

// Stop stops the runner.
func (r *Runner) Stop() {
	close(r.queue)
}

// Package api is Tally's JSON HTTP API (version 1). Every request under /v1/ presents an API key as
// "Authorization: Bearer <token>"; the key acts as the member who created it, in that member's organization, with the
// member's current role. The API only ever shows the caller's organization's data.
package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"io"
	"log/slog"
	"net/http"
	"regexp"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

// Options configure a Server.
type Options struct {
	Clock         clock.Clock            // nil: clock.Real
	Payments      *payments.Service      // required
	Subscriptions *subscriptions.Service // required
	Webhooks      *webhooks.Service      // nil: a service with the default HTTP client and resolver
	Mail          mail.Sender            // nil: an Outbox (nothing is sent)
	Logger        *slog.Logger           // nil: discard
	// BaseURL is the dashboard's address, for links in emails (default "https://app.tally.example").
	BaseURL string
}

// Server serves the API.
type Server struct {
	store   *store.Store
	clock   clock.Clock
	pay     *payments.Service
	subs    *subscriptions.Service
	hooks   *webhooks.Service
	mail    mail.Sender
	log     *slog.Logger
	baseURL string
	mux     *http.ServeMux
	handler http.Handler
}

// New returns a server over a store.
func New(st *store.Store, opt Options) *Server {
	if opt.Payments == nil || opt.Subscriptions == nil {
		panic("api.New: Options.Payments and Options.Subscriptions are required")
	}
	s := &Server{store: st, clock: opt.Clock, pay: opt.Payments, subs: opt.Subscriptions, hooks: opt.Webhooks, mail: opt.Mail, log: opt.Logger,
		baseURL: strings.TrimRight(opt.BaseURL, "/"), mux: http.NewServeMux()}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.hooks == nil {
		s.hooks = webhooks.New(webhooks.Options{Store: st, Clock: s.clock})
	}
	if s.mail == nil {
		s.mail = &mail.Outbox{}
	}
	if s.log == nil {
		s.log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	if s.baseURL == "" {
		s.baseURL = "https://app.tally.example"
	}
	s.routes()
	s.handler = s.withRequestID(s.recoverPanics(s.mux))
	return s
}

// ServeHTTP implements http.Handler.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.handler.ServeHTTP(w, r) }

func (s *Server) routes() {
	m := s.mux
	m.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	m.HandleFunc("GET /v1/me", s.authed(s.getMe))

	m.HandleFunc("GET /v1/org", s.authed(s.getOrg))
	m.HandleFunc("PATCH /v1/org", s.authed(s.updateOrg))
	m.HandleFunc("GET /v1/members", s.authed(s.listMembers))
	m.HandleFunc("PATCH /v1/members/{user_id}", s.authed(s.updateMember))
	m.HandleFunc("DELETE /v1/members/{user_id}", s.authed(s.removeMember))
	m.HandleFunc("GET /v1/invites", s.authed(s.listInvites))
	m.HandleFunc("POST /v1/invites", s.authed(s.createInvite))
	m.HandleFunc("DELETE /v1/invites/{id}", s.authed(s.revokeInvite))
	m.HandleFunc("POST /v1/invites/accept", s.acceptInvite) // no API key: the token is the credential
	m.HandleFunc("GET /v1/api-keys", s.authed(s.listAPIKeys))
	m.HandleFunc("POST /v1/api-keys", s.authed(s.createAPIKey))
	m.HandleFunc("DELETE /v1/api-keys/{id}", s.authed(s.revokeAPIKey))

	m.HandleFunc("GET /v1/customers", s.authed(s.listCustomers))
	m.HandleFunc("POST /v1/customers", s.authed(s.createCustomer))
	m.HandleFunc("GET /v1/customers/export.csv", s.authed(s.exportCustomers))
	m.HandleFunc("GET /v1/customers/{id}", s.authed(s.getCustomer))
	m.HandleFunc("PATCH /v1/customers/{id}", s.authed(s.updateCustomer))
	m.HandleFunc("DELETE /v1/customers/{id}", s.authed(s.deleteCustomer))

	m.HandleFunc("GET /v1/plans", s.authed(s.listPlans))
	m.HandleFunc("POST /v1/plans", s.authed(s.createPlan))
	m.HandleFunc("GET /v1/plans/{id}", s.authed(s.getPlan))
	m.HandleFunc("PATCH /v1/plans/{id}", s.authed(s.updatePlan))

	m.HandleFunc("GET /v1/subscriptions", s.authed(s.listSubscriptions))
	m.HandleFunc("POST /v1/subscriptions", s.authed(s.createSubscription))
	m.HandleFunc("GET /v1/subscriptions/{id}", s.authed(s.getSubscription))
	m.HandleFunc("PATCH /v1/subscriptions/{id}", s.authed(s.updateSubscription))
	m.HandleFunc("POST /v1/subscriptions/{id}/cancel", s.authed(s.cancelSubscription))
	m.HandleFunc("POST /v1/subscriptions/{id}/usage", s.authed(s.reportUsage))

	m.HandleFunc("GET /v1/invoices", s.authed(s.listInvoices))
	m.HandleFunc("POST /v1/invoices", s.authed(s.createInvoice))
	m.HandleFunc("GET /v1/invoices/{id}", s.authed(s.getInvoice))
	m.HandleFunc("GET /v1/invoices/{id}/lines", s.authed(s.getInvoiceLines))
	m.HandleFunc("POST /v1/invoices/{id}/pay", s.authed(s.payInvoice))
	m.HandleFunc("POST /v1/invoices/{id}/void", s.authed(s.voidInvoice))
	m.HandleFunc("GET /v1/payments", s.authed(s.listPayments))

	m.HandleFunc("GET /v1/webhook-endpoints", s.authed(s.listEndpoints))
	m.HandleFunc("POST /v1/webhook-endpoints", s.authed(s.createEndpoint))
	m.HandleFunc("GET /v1/webhook-endpoints/{id}", s.authed(s.getEndpoint))
	m.HandleFunc("PATCH /v1/webhook-endpoints/{id}", s.authed(s.updateEndpoint))
	m.HandleFunc("DELETE /v1/webhook-endpoints/{id}", s.authed(s.deleteEndpoint))
	m.HandleFunc("GET /v1/webhook-endpoints/{id}/deliveries", s.authed(s.listDeliveries))
	m.HandleFunc("GET /v1/events", s.authed(s.listEvents))
	m.HandleFunc("GET /v1/events/{id}", s.authed(s.getEvent))

	m.HandleFunc("GET /v1/reports/revenue", s.authed(s.revenueReport))
}

// handler is an endpoint that runs for a known member.
type handler func(w http.ResponseWriter, r *http.Request, p auth.Principal)

// authed resolves the request's API key to the member it acts for, or answers 401. Viewers may only read: any other method
// answers 403.
func (s *Server) authed(h handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized", "send an API key as Authorization: Bearer <token>")
			return
		}
		key, ok := s.store.APIKeyByToken(strings.TrimSpace(token))
		if !ok || key.RevokedAt != nil {
			writeError(w, http.StatusUnauthorized, "unauthorized", "unknown or revoked API key")
			return
		}
		m, ok := s.store.Member(key.OrgID, key.UserID)
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized", "the key's owner is no longer a member")
			return
		}
		s.store.TouchAPIKey(key.ID, s.clock.Now())
		p := auth.Principal{OrgID: key.OrgID, UserID: key.UserID, KeyID: key.ID, Role: m.Role}
		if r.Method != http.MethodGet && !auth.CanWrite(p.Role) {
			writeError(w, http.StatusForbidden, "forbidden", "viewers can only read")
			return
		}
		h(w, r, p)
	}
}

type ctxKey int

const requestIDKey ctxKey = 0

var requestIDRe = regexp.MustCompile(`^[A-Za-z0-9._-]{1,128}$`)

// withRequestID gives every request an ID: the caller's X-Request-Id when it is sensible, a new one otherwise. It is sent
// back in the X-Request-Id header.
func (s *Server) withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-Id")
		if !requestIDRe.MatchString(id) {
			b := make([]byte, 8)
			_, _ = rand.Read(b)
			id = "req_" + hex.EncodeToString(b)
		}
		w.Header().Set("X-Request-Id", id)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), requestIDKey, id)))
	})
}

// RequestID returns the ID of the request ctx belongs to.
func RequestID(ctx context.Context) string {
	id, _ := ctx.Value(requestIDKey).(string)
	return id
}

func (s *Server) recoverPanics(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if v := recover(); v != nil {
				s.log.Error("panic", "method", r.Method, "path", r.URL.Path, "panic", v, "request_id", RequestID(r.Context()))
				writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func (s *Server) publish(ctx context.Context, orgID, typ string, data any) {
	if err := s.hooks.Publish(ctx, orgID, typ, data); err != nil {
		s.log.Error("publish event", "type", typ, "err", err)
	}
}
package api

import (
	"errors"
	"net/http"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

func subKey(s store.Subscription) cursor { return cursor{T: s.CreatedAt, ID: s.ID} }

func (s *Server) subError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, subscriptions.ErrPlanInactive):
		writeError(w, http.StatusUnprocessableEntity, "plan_inactive", err.Error())
	case errors.Is(err, subscriptions.ErrCanceled):
		writeError(w, http.StatusConflict, "subscription_canceled", err.Error())
	default:
		s.payError(w, err)
	}
}

func (s *Server) listSubscriptions(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	subs := s.store.Subscriptions(p.OrgID, store.SubscriptionFilter{CustomerID: q.Get("customer_id"), Status: store.SubStatus(q.Get("status"))})
	items, next := pageOf(subs, subKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		CustomerID      string `json:"customer_id"`
		PlanID          string `json:"plan_id"`
		Quantity        int    `json:"quantity"`
		DiscountPercent int    `json:"discount_percent"`
	}
	if !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Create(r.Context(), p.OrgID, subscriptions.CreateInput{CustomerID: in.CustomerID, PlanID: in.PlanID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent})
	if err != nil && sub.ID == "" {
		s.subError(w, err)
		return
	}
	if err != nil {
		s.log.Error("first invoice", "subscription", sub.ID, "err", err)
	}
	writeJSON(w, http.StatusCreated, sub)
}

func (s *Server) getSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	sub, ok := s.store.Subscription(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such subscription")
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

func (s *Server) updateSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		PlanID   *string `json:"plan_id"`
		Quantity *int    `json:"quantity"`
	}
	if !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Update(r.Context(), p.OrgID, r.PathValue("id"), subscriptions.UpdateInput{PlanID: in.PlanID, Quantity: in.Quantity})
	if err != nil {
		s.subError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

func (s *Server) cancelSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		AtPeriodEnd bool `json:"at_period_end"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Cancel(r.Context(), p.OrgID, r.PathValue("id"), in.AtPeriodEnd)
	if err != nil {
		s.subError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

// reportUsage records usage of a metered subscription: {"quantity": n, "timestamp": RFC 3339 (default now)}.
func (s *Server) reportUsage(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Quantity  int64      `json:"quantity"`
		Timestamp *time.Time `json:"timestamp"`
	}
	if !decode(w, r, &in) {
		return
	}
	now := s.clock.Now()
	at := now
	if in.Timestamp != nil {
		at = *in.Timestamp
	}
	u, err := s.store.AddUsage(p.OrgID, r.PathValue("id"), in.Quantity, at, now)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, u)
}
package api

import (
	"errors"
	"fmt"
	"net/http"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// invoiceView is an invoice as the API shows it: with its totals, a one-line description and its customer.
type invoiceView struct {
	store.Invoice
	billing.Totals
	TotalFormatted string       `json:"total_formatted"`
	Description    string       `json:"description"`
	Customer       *customerRef `json:"customer"`
}

// customerRef is the customer shown on an invoice; null when the customer was deleted.
type customerRef struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

func newInvoiceView(inv store.Invoice, c *store.Customer) invoiceView {
	t := billing.Compute(inv)
	v := invoiceView{Invoice: inv, Totals: t, TotalFormatted: money.Format(t.Total, inv.Currency), Description: describe(inv.Lines)}
	if c != nil {
		v.Customer = &customerRef{ID: c.ID, Name: c.Name, Email: c.Email}
	}
	return v
}

// describe is the invoice's first line, and how many more there are.
func describe(lines []store.Line) string {
	d := lines[0].Description
	if len(lines) > 1 {
		d += fmt.Sprintf(" and %d more", len(lines)-1)
	}
	return d
}

func (s *Server) viewInvoice(inv store.Invoice) invoiceView {
	if c, ok := s.store.Customer(inv.OrgID, inv.CustomerID); ok {
		return newInvoiceView(inv, &c)
	}
	return newInvoiceView(inv, nil)
}

func findCustomer(cs []store.Customer, id string) *store.Customer {
	for i := range cs {
		if cs[i].ID == id {
			return &cs[i]
		}
	}
	return nil
}

func invoiceViewKey(v invoiceView) cursor { return cursor{T: v.CreatedAt, ID: v.ID} }

// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
// or with ?status=.
func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	status := store.InvoiceStatus(q.Get("status"))
	if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
		writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
		return
	}
	invs := s.store.ListInvoices(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status})
	customers := s.store.Customers(p.OrgID)
	views := make([]invoiceView, 0, len(invs))
	for _, inv := range invs {
		views = append(views, newInvoiceView(inv, findCustomer(customers, inv.CustomerID)))
	}
	items, next := pageOf(views, invoiceViewKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		CustomerID      string         `json:"customer_id"`
		Currency        money.Currency `json:"currency"`
		Lines           []store.Line   `json:"lines"`
		DiscountPercent int            `json:"discount_percent"`
	}
	if !decode(w, r, &in) {
		return
	}
	if len(in.Lines) == 0 {
		writeError(w, http.StatusUnprocessableEntity, "invalid", "an invoice needs at least one line")
		return
	}
	for _, l := range in.Lines {
		if strings.TrimSpace(l.Description) == "" || l.Quantity <= 0 || l.UnitAmount < 0 {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "each line needs a description, a positive quantity and a unit amount that is not negative")
			return
		}
	}
	inv, err := s.store.CreateInvoice(store.Invoice{OrgID: p.OrgID, CustomerID: in.CustomerID, Currency: in.Currency, Lines: in.Lines, DiscountPercent: in.DiscountPercent}, s.clock.Now())
	if err != nil {
		if errors.Is(err, store.ErrCustomerOrgMismatch) {
			writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", fmt.Sprintf("customer %s belongs to another organization", in.CustomerID))
			return
		}
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusCreated, s.viewInvoice(inv))
}

func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.InvoiceByID(r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	type lineView struct {
		store.Line
		Amount int64 `json:"amount"`
	}
	items := []lineView{}
	for _, l := range inv.Lines {
		items = append(items, lineView{Line: l, Amount: l.Amount()})
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		PaymentMethod string `json:"payment_method"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
	if err != nil {
		s.payError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
}

func (s *Server) payError(w http.ResponseWriter, err error) {
	var decline *payments.DeclineError
	switch {
	case errors.As(err, &decline):
		writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
	case errors.Is(err, payments.ErrAlreadyPaid):
		writeError(w, http.StatusConflict, "already_paid", err.Error())
	case errors.Is(err, payments.ErrInvoiceVoid):
		writeError(w, http.StatusConflict, "invoice_void", err.Error())
	case errors.Is(err, payments.ErrNoPaymentMethod):
		writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
	case errors.Is(err, payments.ErrUnavailable):
		writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
	default:
		s.storeError(w, err)
	}
}

func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	now := s.clock.Now()
	inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
		switch inv.Status {
		case store.InvoicePaid:
			return payments.ErrAlreadyPaid
		case store.InvoiceVoid:
			return payments.ErrInvoiceVoid
		}
		inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
		return nil
	})
	if err != nil {
		s.payError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

func (s *Server) listPayments(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	writeJSON(w, http.StatusOK, list{Items: s.store.Payments(p.OrgID, r.URL.Query().Get("invoice_id"))})
}
package api

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"time"

	"example.com/tally/internal/store"
)

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// writeError answers {"error": code, "message": message}.
func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]string{"error": code, "message": message})
}

// decode reads a JSON body (at most 1 MiB) into v, or answers 400 and returns false.
func decode(w http.ResponseWriter, r *http.Request, v any) bool {
	dec := json.NewDecoder(io.LimitReader(r.Body, 1<<20))
	if err := dec.Decode(v); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "the body is not valid JSON: "+err.Error())
		return false
	}
	return true
}

// storeError answers for an error from the store or a service.
func (s *Server) storeError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found", "no such object")
	case errors.Is(err, store.ErrEmailTaken):
		writeError(w, http.StatusConflict, "email_taken", err.Error())
	case errors.Is(err, store.ErrAlreadyMember):
		writeError(w, http.StatusConflict, "already_member", err.Error())
	case errors.Is(err, store.ErrConflict):
		writeError(w, http.StatusConflict, "conflict", err.Error())
	case errors.Is(err, store.ErrCustomerOrgMismatch):
		writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", err.Error())
	case errors.Is(err, store.ErrInvalid):
		writeError(w, http.StatusUnprocessableEntity, "invalid", err.Error())
	default:
		s.log.Error("request failed", "err", err)
		writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
	}
}

// list is the shape of every list response. NextCursor is set when there is another page.
type list struct {
	Items      any    `json:"items"`
	NextCursor string `json:"next_cursor,omitempty"`
}

// page is a request for one page of a list: ?limit= (1 to 100, default 20) and ?cursor= (from the previous page).
type page struct {
	limit int
	after *cursor
}

// cursor is where a page starts: after the item with this creation time and ID.
type cursor struct {
	T  time.Time `json:"t"`
	ID string    `json:"id"`
}

func (c cursor) less(o cursor) bool {
	if !c.T.Equal(o.T) {
		return c.T.Before(o.T)
	}
	return c.ID < o.ID
}

// parsePage reads ?limit and ?cursor, or answers 400 and returns false.
func parsePage(w http.ResponseWriter, r *http.Request) (page, bool) {
	p := page{limit: 20}
	if v := r.URL.Query().Get("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 || n > 100 {
			writeError(w, http.StatusBadRequest, "invalid_limit", "limit is a whole number from 1 to 100")
			return page{}, false
		}
		p.limit = n
	}
	if v := r.URL.Query().Get("cursor"); v != "" {
		b, err := base64.RawURLEncoding.DecodeString(v)
		var c cursor
		if err != nil || json.Unmarshal(b, &c) != nil || c.ID == "" {
			writeError(w, http.StatusBadRequest, "invalid_cursor", "the cursor is not one this API gave out")
			return page{}, false
		}
		p.after = &c
	}
	return p, true
}

func encodeCursor(c cursor) string {
	b, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(b)
}

// pageOf returns one page of items, which are sorted by key (creation time, then ID), and the cursor of the next page.
func pageOf[T any](items []T, key func(T) cursor, p page) ([]T, string) {
	start := 0
	if p.after != nil {
		start = len(items)
		for i, it := range items {
			if p.after.less(key(it)) {
				start = i
				break
			}
		}
	}
	end := min(start+p.limit, len(items))
	out := items[start:end]
	next := ""
	if end < len(items) && len(out) > 0 {
		next = encodeCursor(key(out[len(out)-1]))
	}
	return out, next
}

// Package api is Tally's JSON HTTP API (version 1). Every request under /v1/ presents an API key as
// "Authorization: Bearer <token>"; the key acts as the member who created it, in that member's organization, with the
// member's current role. The API only ever shows the caller's organization's data.
package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"io"
	"log/slog"
	"net/http"
	"regexp"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

// Options configure a Server.
type Options struct {
	Clock         clock.Clock            // nil: clock.Real
	Payments      *payments.Service      // required
	Subscriptions *subscriptions.Service // required
	Webhooks      *webhooks.Service      // nil: a service with the default HTTP client and resolver
	Mail          mail.Sender            // nil: an Outbox (nothing is sent)
	Logger        *slog.Logger           // nil: discard
	// BaseURL is the dashboard's address, for links in emails (default "https://app.tally.example").
	BaseURL string
}

// Server serves the API.
type Server struct {
	store   *store.Store
	clock   clock.Clock
	pay     *payments.Service
	subs    *subscriptions.Service
	hooks   *webhooks.Service
	mail    mail.Sender
	log     *slog.Logger
	baseURL string
	mux     *http.ServeMux
	handler http.Handler
}

// New returns a server over a store.
func New(st *store.Store, opt Options) *Server {
	if opt.Payments == nil || opt.Subscriptions == nil {
		panic("api.New: Options.Payments and Options.Subscriptions are required")
	}
	s := &Server{store: st, clock: opt.Clock, pay: opt.Payments, subs: opt.Subscriptions, hooks: opt.Webhooks, mail: opt.Mail, log: opt.Logger,
		baseURL: strings.TrimRight(opt.BaseURL, "/"), mux: http.NewServeMux()}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.hooks == nil {
		s.hooks = webhooks.New(webhooks.Options{Store: st, Clock: s.clock})
	}
	if s.mail == nil {
		s.mail = &mail.Outbox{}
	}
	if s.log == nil {
		s.log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	if s.baseURL == "" {
		s.baseURL = "https://app.tally.example"
	}
	s.routes()
	s.handler = s.withRequestID(s.recoverPanics(s.mux))
	return s
}

// ServeHTTP implements http.Handler.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.handler.ServeHTTP(w, r) }

func (s *Server) routes() {
	m := s.mux
	m.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	m.HandleFunc("GET /v1/me", s.authed(s.getMe))

	m.HandleFunc("GET /v1/org", s.authed(s.getOrg))
	m.HandleFunc("PATCH /v1/org", s.authed(s.updateOrg))
	m.HandleFunc("GET /v1/members", s.authed(s.listMembers))
	m.HandleFunc("PATCH /v1/members/{user_id}", s.authed(s.updateMember))
	m.HandleFunc("DELETE /v1/members/{user_id}", s.authed(s.removeMember))
	m.HandleFunc("GET /v1/invites", s.authed(s.listInvites))
	m.HandleFunc("POST /v1/invites", s.authed(s.createInvite))
	m.HandleFunc("DELETE /v1/invites/{id}", s.authed(s.revokeInvite))
	m.HandleFunc("POST /v1/invites/accept", s.acceptInvite) // no API key: the token is the credential
	m.HandleFunc("GET /v1/api-keys", s.authed(s.listAPIKeys))
	m.HandleFunc("POST /v1/api-keys", s.authed(s.createAPIKey))
	m.HandleFunc("DELETE /v1/api-keys/{id}", s.authed(s.revokeAPIKey))

	m.HandleFunc("GET /v1/customers", s.authed(s.listCustomers))
	m.HandleFunc("POST /v1/customers", s.authed(s.createCustomer))
	m.HandleFunc("GET /v1/customers/export.csv", s.authed(s.exportCustomers))
	m.HandleFunc("GET /v1/customers/{id}", s.authed(s.getCustomer))
	m.HandleFunc("PATCH /v1/customers/{id}", s.authed(s.updateCustomer))
	m.HandleFunc("DELETE /v1/customers/{id}", s.authed(s.deleteCustomer))

	m.HandleFunc("GET /v1/plans", s.authed(s.listPlans))
	m.HandleFunc("POST /v1/plans", s.authed(s.createPlan))
	m.HandleFunc("GET /v1/plans/{id}", s.authed(s.getPlan))
	m.HandleFunc("PATCH /v1/plans/{id}", s.authed(s.updatePlan))

	m.HandleFunc("GET /v1/subscriptions", s.authed(s.listSubscriptions))
	m.HandleFunc("POST /v1/subscriptions", s.authed(s.createSubscription))
	m.HandleFunc("GET /v1/subscriptions/{id}", s.authed(s.getSubscription))
	m.HandleFunc("PATCH /v1/subscriptions/{id}", s.authed(s.updateSubscription))
	m.HandleFunc("POST /v1/subscriptions/{id}/cancel", s.authed(s.cancelSubscription))
	m.HandleFunc("POST /v1/subscriptions/{id}/usage", s.authed(s.reportUsage))

	m.HandleFunc("GET /v1/invoices", s.authed(s.listInvoices))
	m.HandleFunc("POST /v1/invoices", s.authed(s.createInvoice))
	m.HandleFunc("GET /v1/invoices/{id}", s.authed(s.getInvoice))
	m.HandleFunc("GET /v1/invoices/{id}/lines", s.authed(s.getInvoiceLines))
	m.HandleFunc("POST /v1/invoices/{id}/pay", s.authed(s.payInvoice))
	m.HandleFunc("POST /v1/invoices/{id}/void", s.authed(s.voidInvoice))
	m.HandleFunc("GET /v1/payments", s.authed(s.listPayments))

	m.HandleFunc("GET /v1/webhook-endpoints", s.authed(s.listEndpoints))
	m.HandleFunc("POST /v1/webhook-endpoints", s.authed(s.createEndpoint))
	m.HandleFunc("GET /v1/webhook-endpoints/{id}", s.authed(s.getEndpoint))
	m.HandleFunc("PATCH /v1/webhook-endpoints/{id}", s.authed(s.updateEndpoint))
	m.HandleFunc("DELETE /v1/webhook-endpoints/{id}", s.authed(s.deleteEndpoint))
	m.HandleFunc("GET /v1/webhook-endpoints/{id}/deliveries", s.authed(s.listDeliveries))
	m.HandleFunc("GET /v1/events", s.authed(s.listEvents))
	m.HandleFunc("GET /v1/events/{id}", s.authed(s.getEvent))

	m.HandleFunc("GET /v1/reports/revenue", s.authed(s.revenueReport))
}

// handler is an endpoint that runs for a known member.
type handler func(w http.ResponseWriter, r *http.Request, p auth.Principal)

// authed resolves the request's API key to the member it acts for, or answers 401. Viewers may only read: any other method
// answers 403.
func (s *Server) authed(h handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized", "send an API key as Authorization: Bearer <token>")
			return
		}
		key, ok := s.store.APIKeyByToken(strings.TrimSpace(token))
		if !ok || key.RevokedAt != nil {
			writeError(w, http.StatusUnauthorized, "unauthorized", "unknown or revoked API key")
			return
		}
		m, ok := s.store.Member(key.OrgID, key.UserID)
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized", "the key's owner is no longer a member")
			return
		}
		s.store.TouchAPIKey(key.ID, s.clock.Now())
		p := auth.Principal{OrgID: key.OrgID, UserID: key.UserID, KeyID: key.ID, Role: m.Role}
		if r.Method != http.MethodGet && !auth.CanWrite(p.Role) {
			writeError(w, http.StatusForbidden, "forbidden", "viewers can only read")
			return
		}
		h(w, r, p)
	}
}

type ctxKey int

const requestIDKey ctxKey = 0

var requestIDRe = regexp.MustCompile(`^[A-Za-z0-9._-]{1,128}$`)

// withRequestID gives every request an ID: the caller's X-Request-Id when it is sensible, a new one otherwise. It is sent
// back in the X-Request-Id header.
func (s *Server) withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-Id")
		if !requestIDRe.MatchString(id) {
			b := make([]byte, 8)
			_, _ = rand.Read(b)
			id = "req_" + hex.EncodeToString(b)
		}
		w.Header().Set("X-Request-Id", id)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), requestIDKey, id)))
	})
}

// RequestID returns the ID of the request ctx belongs to.
func RequestID(ctx context.Context) string {
	id, _ := ctx.Value(requestIDKey).(string)
	return id
}

func (s *Server) recoverPanics(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if v := recover(); v != nil {
				s.log.Error("panic", "method", r.Method, "path", r.URL.Path, "panic", v, "request_id", RequestID(r.Context()))
				writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func (s *Server) publish(ctx context.Context, orgID, typ string, data any) {
	if err := s.hooks.Publish(ctx, orgID, typ, data); err != nil {
		s.log.Error("publish event", "type", typ, "err", err)
	}
}
package api

import (
	"errors"
	"net/http"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

func subKey(s store.Subscription) cursor { return cursor{T: s.CreatedAt, ID: s.ID} }

func (s *Server) subError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, subscriptions.ErrPlanInactive):
		writeError(w, http.StatusUnprocessableEntity, "plan_inactive", err.Error())
	case errors.Is(err, subscriptions.ErrCanceled):
		writeError(w, http.StatusConflict, "subscription_canceled", err.Error())
	default:
		s.payError(w, err)
	}
}

func (s *Server) listSubscriptions(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	subs := s.store.Subscriptions(p.OrgID, store.SubscriptionFilter{CustomerID: q.Get("customer_id"), Status: store.SubStatus(q.Get("status"))})
	items, next := pageOf(subs, subKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		CustomerID      string `json:"customer_id"`
		PlanID          string `json:"plan_id"`
		Quantity        int    `json:"quantity"`
		DiscountPercent int    `json:"discount_percent"`
	}
	if !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Create(r.Context(), p.OrgID, subscriptions.CreateInput{CustomerID: in.CustomerID, PlanID: in.PlanID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent})
	if err != nil && sub.ID == "" {
		s.subError(w, err)
		return
	}
	if err != nil {
		s.log.Error("first invoice", "subscription", sub.ID, "err", err)
	}
	writeJSON(w, http.StatusCreated, sub)
}

func (s *Server) getSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	sub, ok := s.store.Subscription(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such subscription")
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

func (s *Server) updateSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		PlanID   *string `json:"plan_id"`
		Quantity *int    `json:"quantity"`
	}
	if !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Update(r.Context(), p.OrgID, r.PathValue("id"), subscriptions.UpdateInput{PlanID: in.PlanID, Quantity: in.Quantity})
	if err != nil {
		s.subError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

func (s *Server) cancelSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		AtPeriodEnd bool `json:"at_period_end"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	sub, err := s.subs.Cancel(r.Context(), p.OrgID, r.PathValue("id"), in.AtPeriodEnd)
	if err != nil {
		s.subError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, sub)
}

// reportUsage records usage of a metered subscription: {"quantity": n, "timestamp": RFC 3339 (default now)}.
func (s *Server) reportUsage(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Quantity  int64      `json:"quantity"`
		Timestamp *time.Time `json:"timestamp"`
	}
	if !decode(w, r, &in) {
		return
	}
	now := s.clock.Now()
	at := now
	if in.Timestamp != nil {
		at = *in.Timestamp
	}
	u, err := s.store.AddUsage(p.OrgID, r.PathValue("id"), in.Quantity, at, now)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, u)
}
