func TestComputeWithCoupon(t *testing.T) {
	lines := []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 1500}, {Description: "Setup", Quantity: 1, UnitAmount: 999}}

	// A percent coupon discounts the subtotal in place of the subscription's discount; tax is on the discounted amount.
	// subtotal 5499; discount 549.9 -> 550; taxable 4949; tax 408.2925 -> 408
	got := Compute(store.Invoice{Lines: lines, DiscountPercent: 50, Coupon: "TEN", CouponPercentOff: 10, TaxRateBP: 825})
	if want := (Totals{Subtotal: 5499, Discount: 550, Tax: 408, Total: 5357}); got != want {
		t.Fatalf("percent coupon: Compute = %+v, want %+v", got, want)
	}

	// An amount coupon takes that amount off; tax 3499 * 8.25% = 288.6675 -> 289
	got = Compute(store.Invoice{Lines: lines, Coupon: "OFF20", CouponAmountOff: 2000, TaxRateBP: 825})
	if want := (Totals{Subtotal: 5499, Discount: 2000, Tax: 289, Total: 3788}); got != want {
		t.Fatalf("amount coupon: Compute = %+v, want %+v", got, want)
	}

	// An amount coupon is never more than the subtotal.
	got = Compute(store.Invoice{Lines: lines, Coupon: "BIG", CouponAmountOff: 999999})
	if want := (Totals{Subtotal: 5499, Discount: 5499, Tax: 0, Total: 0}); got != want {
		t.Fatalf("large amount coupon: Compute = %+v, want %+v", got, want)
	}
}

